-- Cumulative Stage 1 + Stage 2 v3 acceptance; one psql session throughout.
\set ON_ERROR_STOP on
SET TIME ZONE 'UTC';
\pset format unaligned
\pset null 'NULL'
CREATE OR REPLACE FUNCTION s2_setup(c text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 TRUNCATE maintenance_request; INSERT INTO equipment(equipment_id,status) VALUES ('eq-stage1-known','available'),('eq-stage1-other','available') ON CONFLICT(equipment_id) DO UPDATE SET status=EXCLUDED.status;
 IF (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION '% setup failed',c; END IF; END $$;
CREATE OR REPLACE FUNCTION s2_report(r text,t timestamptz) RETURNS void LANGUAGE plpgsql AS $$ BEGIN PERFORM report_equipment_fault(r,'eq-stage1-known','reporter-stage1',t,'Hydraulic pressure warning observed'); END $$;
CREATE OR REPLACE FUNCTION s2_reject_schedule(a text,r text,s timestamptz) RETURNS void LANGUAGE plpgsql AS $$ BEGIN PERFORM schedule_maintenance(a,r,s); RAISE EXCEPTION 'unexpected schedule acceptance'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='unexpected schedule acceptance' THEN RAISE; END IF; END $$;
CREATE OR REPLACE FUNCTION s2_reject_complete(a text,r text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN PERFORM complete_maintenance(a,r); RAISE EXCEPTION 'unexpected completion acceptance'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='unexpected completion acceptance' THEN RAISE; END IF; END $$;
CREATE OR REPLACE FUNCTION s2_state(c text,r text,st text,s timestamptz,rep timestamptz,done boolean) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE request_id=r AND equipment_id='eq-stage1-known' AND reported_by='reporter-stage1' AND reported_at=rep AND description='Hydraulic pressure warning observed' AND status=st AND scheduled_for IS NOT DISTINCT FROM s AND CASE WHEN done THEN completed_at IS NOT NULL ELSE completed_at IS NULL END)<>1 OR (SELECT count(*) FROM maintenance_request)<>1 THEN RAISE EXCEPTION '% row/count gate failed',c; END IF; END $$;
CREATE OR REPLACE FUNCTION s2_same(c text,r text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF (SELECT count(*) FROM s2_pre_call)<>1 OR (SELECT count(*) FROM maintenance_request)<>1 OR (SELECT count(*) FROM maintenance_request m JOIN s2_pre_call p ON m.request_id IS NOT DISTINCT FROM p.request_id AND m.equipment_id IS NOT DISTINCT FROM p.equipment_id AND m.reported_by IS NOT DISTINCT FROM p.reported_by AND m.reported_at IS NOT DISTINCT FROM p.reported_at AND m.description IS NOT DISTINCT FROM p.description AND m.status IS NOT DISTINCT FROM p.status AND m.scheduled_for IS NOT DISTINCT FROM p.scheduled_for AND m.completed_at IS NOT DISTINCT FROM p.completed_at WHERE m.request_id=r)<>1 THEN RAISE EXCEPTION '% rejected call mutated request',c; END IF; END $$;
CREATE OR REPLACE FUNCTION s2_clock(c text,r text,b timestamptz,a timestamptz) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF (SELECT completed_at BETWEEN b AND a AND completed_at>=reported_at FROM maintenance_request WHERE request_id=r) IS NOT TRUE THEN RAISE EXCEPTION '% completion clock gate failed',c; END IF; END $$;
SELECT 'authorization_fixture' observation,actor_evidence,role_name FROM stage2_authorization_fixture ORDER BY role_name;

-- Each S2-01..S2-07 prerequisite is time-aligned as required by v3.
-- S2-01
SELECT s2_setup('S2-01'); SELECT clock_timestamp() lifecycle_report_db_before \gset s201_
SELECT 'S2-01 report input' observation,'req-stage2-base' request_id,'eq-stage1-known' equipment_id,'reporter-stage1' reported_by,:'s201_lifecycle_report_db_before' reported_at,'Hydraulic pressure warning observed' description; SELECT s2_report('req-stage2-base',:'s201_lifecycle_report_db_before'::timestamptz); SELECT 'S2-01 report accepted' outcome; SELECT 'S2-01 open row' observation,* FROM maintenance_request; SELECT count(*) request_count FROM maintenance_request; SELECT s2_state('S2-01 prerequisite','req-stage2-base','open',NULL,:'s201_lifecycle_report_db_before'::timestamptz,false);
SELECT clock_timestamp() db_before \gset s201_
SELECT (:'s201_db_before'::timestamptz+interval '48 hours') scheduled \gset s201_
SELECT 'S2-01 schedule input' observation,'stage2-coordinator-fixture' actor,'maintenance_coordinator' authorization,'req-stage2-base' request_id,:'s201_scheduled' scheduled_for; SELECT schedule_maintenance('stage2-coordinator-fixture','req-stage2-base',:'s201_scheduled'::timestamptz); SELECT clock_timestamp() db_after \gset s201_
SELECT 'S2-01 accepted clock' observation,:'s201_db_before' db_before,:'s201_db_after' db_after; SELECT 1/CASE WHEN :'s201_scheduled'::timestamptz>:'s201_db_after'::timestamptz THEN 1 ELSE 0 END s201_future_gate; SELECT 'S2-01 row' observation,* FROM maintenance_request; SELECT count(*) request_count FROM maintenance_request; SELECT s2_state('S2-01','req-stage2-base','scheduled',:'s201_scheduled'::timestamptz,:'s201_lifecycle_report_db_before'::timestamptz,false);

-- S2-02
SELECT s2_setup('S2-02'); SELECT clock_timestamp() lifecycle_report_db_before \gset s202_
SELECT 'S2-02 report input' observation,'req-stage2-base' request_id,'eq-stage1-known' equipment_id,'reporter-stage1' reported_by,:'s202_lifecycle_report_db_before' reported_at,'Hydraulic pressure warning observed' description; SELECT s2_report('req-stage2-base',:'s202_lifecycle_report_db_before'::timestamptz); SELECT 'S2-02 report accepted' outcome; SELECT 'S2-02 open row' observation,* FROM maintenance_request; SELECT count(*) request_count FROM maintenance_request; SELECT s2_state('S2-02 prerequisite','req-stage2-base','open',NULL,:'s202_lifecycle_report_db_before'::timestamptz,false);
SELECT clock_timestamp() schedule_db_before \gset s202_
SELECT (:'s202_schedule_db_before'::timestamptz+interval '48 hours') scheduled \gset s202_
SELECT 'S2-02 schedule input' observation,'stage2-coordinator-fixture' actor,'maintenance_coordinator' authorization,'req-stage2-base' request_id,:'s202_scheduled' scheduled_for; SELECT schedule_maintenance('stage2-coordinator-fixture','req-stage2-base',:'s202_scheduled'::timestamptz); SELECT clock_timestamp() schedule_db_after \gset s202_
SELECT 1/CASE WHEN :'s202_scheduled'::timestamptz>:'s202_schedule_db_after'::timestamptz THEN 1 ELSE 0 END s202_schedule_gate;
SELECT 'S2-02 pre-completion row' observation,* FROM maintenance_request; SELECT clock_timestamp() db_before \gset s202_
SELECT 'S2-02 complete input' observation,'stage2-technician-fixture' actor,'technician' authorization,'req-stage2-base' request_id; SELECT complete_maintenance('stage2-technician-fixture','req-stage2-base'); SELECT clock_timestamp() db_after \gset s202_
SELECT 'S2-02 accepted clock' observation,:'s202_db_before' db_before,:'s202_db_after' db_after; SELECT 'S2-02 row' observation,* FROM maintenance_request; SELECT count(*) request_count FROM maintenance_request; SELECT s2_state('S2-02','req-stage2-base','completed',:'s202_scheduled'::timestamptz,:'s202_lifecycle_report_db_before'::timestamptz,true); SELECT s2_clock('S2-02','req-stage2-base',:'s202_db_before'::timestamptz,:'s202_db_after'::timestamptz);

-- S2-03 (open completion is rejected without mutation)
SELECT s2_setup('S2-03'); SELECT clock_timestamp() lifecycle_report_db_before \gset s203_
SELECT 'S2-03 report input' observation,'req-stage2-base' request_id,'eq-stage1-known' equipment_id,'reporter-stage1' reported_by,:'s203_lifecycle_report_db_before' reported_at,'Hydraulic pressure warning observed' description; SELECT s2_report('req-stage2-base',:'s203_lifecycle_report_db_before'::timestamptz); SELECT 'S2-03 report accepted' outcome; SELECT 'S2-03 open row' observation,* FROM maintenance_request; SELECT count(*) request_count FROM maintenance_request; SELECT s2_state('S2-03 prerequisite','req-stage2-base','open',NULL,:'s203_lifecycle_report_db_before'::timestamptz,false);
BEGIN; CREATE TEMP TABLE s2_pre_call ON COMMIT DROP AS SELECT request_id,equipment_id,reported_by,reported_at,description,status,scheduled_for,completed_at FROM maintenance_request WHERE request_id='req-stage2-base'; SELECT 'S2-03 pre' observation,* FROM s2_pre_call; SELECT clock_timestamp() db_before \gset s203c_
SELECT 'S2-03 complete input' observation,'stage2-technician-fixture' actor,'technician' authorization,'req-stage2-base' request_id; SELECT s2_reject_complete('stage2-technician-fixture','req-stage2-base'); SELECT clock_timestamp() db_after \gset s203c_
SELECT 'S2-03 rejected clock' observation,:'s203c_db_before' db_before,:'s203c_db_after' db_after; SELECT 'S2-03 after' observation,* FROM maintenance_request; SELECT count(*) request_count FROM maintenance_request; SELECT s2_same('S2-03','req-stage2-base'); COMMIT;

