SELECT s2_setup('S2-04'); SELECT clock_timestamp() lifecycle_report_db_before \gset s204_
SELECT 'S2-04 report input' observation,'req-stage2-base' request_id,'eq-stage1-known' equipment_id,'reporter-stage1' reported_by,:'s204_lifecycle_report_db_before' reported_at,'Hydraulic pressure warning observed' description; SELECT s2_report('req-stage2-base',:'s204_lifecycle_report_db_before'::timestamptz); SELECT 'S2-04 report accepted' outcome; SELECT s2_state('S2-04 prerequisite','req-stage2-base','open',NULL,:'s204_lifecycle_report_db_before'::timestamptz,false); SELECT clock_timestamp() schedule_db_before \gset s204_
