SELECT schedule_maintenance('stage2-coordinator-fixture','req-stage2-base',:'s204_scheduled'::timestamptz); SELECT clock_timestamp() schedule_db_after \gset s204_
SELECT 1/CASE WHEN :'s204_scheduled'::timestamptz>:'s204_schedule_db_after'::timestamptz THEN 1 ELSE 0 END s204_schedule_gate; SELECT 'S2-04 pre-completion row' observation,* FROM maintenance_request; SELECT clock_timestamp() db_before \gset s204c_
SELECT 'S2-04 complete input' observation,'stage2-technician-fixture' actor,'technician' authorization,'req-stage2-base' request_id; SELECT complete_maintenance('stage2-technician-fixture','req-stage2-base'); SELECT clock_timestamp() db_after \gset s204c_
