BEGIN; CREATE TEMP TABLE s2_pre_call ON COMMIT DROP AS SELECT request_id,equipment_id,reported_by,reported_at,description,status,scheduled_for,completed_at FROM maintenance_request WHERE request_id='req-stage2-base'; SELECT 'S2-04 pre' observation,* FROM s2_pre_call; SELECT clock_timestamp() db_before \gset s204r_
SELECT (:'s204r_db_before'::timestamptz+interval '72 hours') retry \gset s204r_
SELECT 'S2-04 schedule input' observation,'stage2-coordinator-fixture' actor,'maintenance_coordinator' authorization,'req-stage2-base' request_id,:'s204r_retry' scheduled_for; SELECT s2_reject_schedule('stage2-coordinator-fixture','req-stage2-base',:'s204r_retry'::timestamptz); SELECT clock_timestamp() db_after \gset s204r_
SELECT 'S2-04 rejected clock' observation,:'s204r_db_before' db_before,:'s204r_db_after' db_after; SELECT 'S2-04 after' observation,* FROM maintenance_request; SELECT count(*) request_count FROM maintenance_request; SELECT s2_same('S2-04','req-stage2-base'); COMMIT;

