SELECT 'S2-08 rejected clock' observation,:'s208_db_before' db_before,:'s208_db_after' db_after; SELECT 'S2-08 counts' observation,count(*) total,count(*) FILTER (WHERE request_id='req-stage2-missing') attempted_id FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request)<>0 OR (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage2-missing')<>0 THEN RAISE EXCEPTION 'S2-08 failed'; END IF; END $$;
