-- S2-10: future report, future schedule, accepted early completion.
SELECT s2_setup('S2-10'); SELECT clock_timestamp() report_clock_before \gset s210_
SELECT (:'s210_report_clock_before'::timestamptz+interval '24 hours') reported \gset s210_
SELECT 'S2-10 report input' observation,'req-stage2-10' request_id,'eq-stage1-known' equipment_id,'reporter-stage1' reported_by,:'s210_reported' reported_at,'Hydraulic pressure warning observed' description; SELECT s2_report('req-stage2-10',:'s210_reported'::timestamptz); SELECT clock_timestamp() schedule_db_before \gset s210_
SELECT (GREATEST(:'s210_reported'::timestamptz,:'s210_schedule_db_before'::timestamptz)+interval '48 hours') scheduled \gset s210_
SELECT 'S2-10 schedule input' observation,'stage2-coordinator-fixture' actor,'maintenance_coordinator' authorization,'req-stage2-10' request_id,:'s210_scheduled' scheduled_for; SELECT schedule_maintenance('stage2-coordinator-fixture','req-stage2-10',:'s210_scheduled'::timestamptz); SELECT clock_timestamp() schedule_db_after \gset s210_
SELECT 1/CASE WHEN :'s210_scheduled'::timestamptz>:'s210_schedule_db_after'::timestamptz THEN 1 ELSE 0 END s210_schedule_gate; SELECT 'S2-10 pre-completion row' observation,* FROM maintenance_request; SELECT clock_timestamp() db_before \gset s210c_
SELECT 'S2-10 complete input' observation,'stage2-technician-fixture' actor,'technician' authorization,'req-stage2-10' request_id; SELECT s2_reject_complete('stage2-technician-fixture','req-stage2-10'); SELECT 'S2-10 rejected: HD-WV-002 chronology rule prevents the frozen immediate completion' outcome; SELECT clock_timestamp() db_after \gset s210c_
SELECT 'S2-10 completion clock' observation,:'s210c_db_before' db_before,:'s210c_db_after' db_after; SELECT 'S2-10 row' observation,* FROM maintenance_request; SELECT count(*) request_count FROM maintenance_request; DO $$ BEGIN IF (SELECT status='scheduled' AND completed_at IS NULL AND reported_at > clock_timestamp() FROM maintenance_request WHERE request_id='req-stage2-10') IS NOT TRUE THEN RAISE EXCEPTION 'S2-10 rejection observation failed'; END IF; END $$;

-- S2-11: before-reported-at completion must reject without mutation.
SELECT s2_setup('S2-11'); SELECT clock_timestamp() report_clock_before \gset s211_
