SELECT 'S2-11 report input' observation,'req-stage2-11' request_id,'eq-stage1-known' equipment_id,'reporter-stage1' reported_by,:'s211_reported' reported_at,'Hydraulic pressure warning observed' description; SELECT s2_report('req-stage2-11',:'s211_reported'::timestamptz); SELECT clock_timestamp() schedule_db_before \gset s211_
SELECT (GREATEST(:'s211_reported'::timestamptz,:'s211_schedule_db_before'::timestamptz)+interval '48 hours') scheduled \gset s211_
SELECT 'S2-11 schedule input' observation,'stage2-coordinator-fixture' actor,'maintenance_coordinator' authorization,'req-stage2-11' request_id,:'s211_scheduled' scheduled_for; SELECT schedule_maintenance('stage2-coordinator-fixture','req-stage2-11',:'s211_scheduled'::timestamptz); SELECT clock_timestamp() schedule_db_after \gset s211_
SELECT 1/CASE WHEN :'s211_scheduled'::timestamptz>:'s211_schedule_db_after'::timestamptz THEN 1 ELSE 0 END s211_schedule_gate; BEGIN; CREATE TEMP TABLE s2_pre_call ON COMMIT DROP AS SELECT request_id,equipment_id,reported_by,reported_at,description,status,scheduled_for,completed_at FROM maintenance_request WHERE request_id='req-stage2-11'; SELECT 'S2-11 pre' observation,* FROM s2_pre_call; SELECT clock_timestamp() db_before \gset s211c_
SELECT 1/CASE WHEN :'s211c_db_before'::timestamptz<:'s211_reported'::timestamptz THEN 1 ELSE 0 END s211_before_reported_gate; SELECT 'S2-11 complete input' observation,'stage2-technician-fixture' actor,'technician' authorization,'req-stage2-11' request_id; SELECT s2_reject_complete('stage2-technician-fixture','req-stage2-11'); SELECT clock_timestamp() db_after \gset s211c_
SELECT 'S2-11 rejected clock' observation,:'s211c_db_before' db_before,:'s211c_db_after' db_after; SELECT 'S2-11 after' observation,* FROM maintenance_request; SELECT count(*) request_count FROM maintenance_request; SELECT s2_same('S2-11','req-stage2-11'); COMMIT;
SELECT 'STAGE2_CUMULATIVE_ACCEPTANCE_V3_INCONCLUSIVE_S2-10' result,current_database() database_name,current_schema() schema_name;
DO $$ BEGIN RAISE EXCEPTION 'S2-10 cannot satisfy its frozen immediate-completion fixture while HD-WV-002 requires completed_at >= reported_at'; END $$;
